var manager = await FoundryLocalManager.CreateAsync(configuration, logger, cancellationToken);
var catalog = await manager.GetCatalogAsync(cancellationToken);
var cached = await catalog.GetCachedModelsAsync(cancellationToken);
var loaded = await catalog.GetLoadedModelsAsync(cancellationToken);
return new FoundryDiscoveryResult(catalog, cached, loaded);

var model = await _foundryClient.GetModelAsync(modelId, cancellationToken);
await model.LoadAsync(cancellationToken);
var chatClient = await model.GetChatClientAsync(cancellationToken);
return chatClient.AsIChatClient();

try
{
